INSERT INTO feature VALUES('memory-readmission','effects','Holds replayed by the kernel','temporary-access','partial','notable',NULL,'The kernel has no store, so readmission simulates a hold. A hold whose accesses stand on the spine of a block of its own, at the whole place, crosses as its state-passing reduct, which passes the held value along the block as a value. An exclusive access answers its result beside the value that its view leaves, and a shared view and a consuming read answer the held value. A match''s arms and a bound block read the hold as blocks of their own, and a slot that the rest reads after them is fixed in them, so the match keeps its motive. A fork''s parent runs as the rest of the block, and the reduct keeps the end that the fork opens. The kernel types the reduct, so a reduct that leaves the wrong value is the kernel''s refusal; the checker alone decides linear use. A receiver, a place at an index, an access under a handler, a view in a thunk, a buffer and an arm that writes a hold that the rest reads after the match cross next (#1626).','core-checker','corpus/model/control/accessor-counter.gandr corpus/model/control/accessor-shared.gandr corpus/model/control/held-unique.gandr corpus/model/control/joined-scope.gandr corpus/model/strings/views.gandr crates/core-checker-bridge/src/bridge/tests.rs::a_lexical_hold_crosses_as_its_state_passing_reduct_6609 crates/core-checker-bridge/src/bridge/tests.rs::a_reduct_leaving_the_wrong_value_is_the_kernel_s_rejection_6609 crates/core-checker-bridge/src/bridge/tests.rs::a_hold_read_across_a_case_s_arms_crosses_as_its_reduct_6641 crates/core-checker-bridge/src/bridge/tests.rs::an_arm_answering_the_wrong_value_is_the_kernel_s_rejection_6641','corpus/ledger/features/memory-readmission.gandr','#1626');
